import { registerSW } from 'virtual:pwa-register';
import { noUpdates, updateSource, type UpdateSource } from './updates';

// Registers the service worker (generated by vite-plugin-pwa) and exposes its
// update state. Imported only by main.tsx, so unit tests never load the virtual module.

/** How often an open app checks for a new version. */
const CHECK_EVERY_MS = 60 * 60 * 1000;

export function registerServiceWorker(): UpdateSource {
  if (typeof navigator === 'undefined' || !('serviceWorker' in navigator) || location.protocol === 'file:') return noUpdates;
  let updateSW: (reload?: boolean) => Promise<void> = async () => {};
  const source = updateSource(() => updateSW(true));
  updateSW = registerSW({
    onNeedRefresh: () => source.setNeedRefresh(true),
    onRegisteredSW(_url, reg) {
      if (reg) setInterval(() => void reg.update().catch(() => undefined), CHECK_EVERY_MS);
    },
    onRegisterError: (e) => console.error('Service worker registration failed; the app still works online', e),
  });
  return source;
}
